import queue


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many elements of xs a bounded queue accepts without blocking.

    A queue with capacity `cap` is created and each element of xs is offered
    in order using a non-blocking put. Counting stops at the first put that
    fails because the queue is full. A capacity of zero or less means the
    queue can hold nothing, so no element is accepted.
    """
    if cap <= 0:
        # queue.Queue treats maxsize <= 0 as unbounded, so handle it here.
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_accepted_stops_when_full() -> None:
    assert accepted(2, [10, 20, 30, 40]) == 2


def test_accepted_cap_larger_than_input() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_accepted_cap_equals_length() -> None:
    assert accepted(3, [1, 2, 3]) == 3


def test_accepted_empty_input() -> None:
    assert accepted(5, []) == 0


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_negative_capacity() -> None:
    assert accepted(-3, [1, 2, 3]) == 0


def test_accepted_duplicates_are_counted() -> None:
    assert accepted(3, [7, 7, 7, 7, 7]) == 3


def test_accepted_single_slot() -> None:
    assert accepted(1, [4, 5]) == 1
